CREATE TABLE semio_presentation_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE semio_presentation_master (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_presentation_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE semio_presentation_layout (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_presentation_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, master_id INTEGER NOT NULL REFERENCES semio_presentation_master(id));
CREATE TABLE semio_presentation_slide (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_presentation_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, layout_id INTEGER REFERENCES semio_presentation_layout(id), notes_collection_id INTEGER NOT NULL REFERENCES semio_presentation_collection(id));
CREATE TABLE semio_presentation_shape (id INTEGER PRIMARY KEY, master_id INTEGER REFERENCES semio_presentation_master(id), layout_id INTEGER REFERENCES semio_presentation_layout(id), slide_id INTEGER REFERENCES semio_presentation_slide(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL, x REAL, y REAL, width REAL, height REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, width_ieee754_bits INTEGER, width_numeric_class TEXT, height_ieee754_bits INTEGER, height_numeric_class TEXT);
CREATE TABLE semio_presentation_text_box (id INTEGER PRIMARY KEY REFERENCES semio_presentation_shape(id), collection_id INTEGER NOT NULL REFERENCES semio_presentation_collection(id));
CREATE TABLE semio_presentation_picture (id INTEGER PRIMARY KEY REFERENCES semio_presentation_shape(id), asset_id TEXT NOT NULL, mime TEXT NOT NULL, bytes BLOB NOT NULL);
CREATE TABLE semio_presentation_shape_table (id INTEGER PRIMARY KEY REFERENCES semio_presentation_shape(id));
CREATE TABLE semio_presentation_shape_table_row (id INTEGER PRIMARY KEY, table_id INTEGER NOT NULL REFERENCES semio_presentation_shape_table(id), ordinal INTEGER NOT NULL);
CREATE TABLE semio_presentation_shape_table_cell (id INTEGER PRIMARY KEY, row_id INTEGER NOT NULL REFERENCES semio_presentation_shape_table_row(id), ordinal INTEGER NOT NULL, collection_id INTEGER NOT NULL REFERENCES semio_presentation_collection(id));
CREATE TABLE semio_presentation_placeholder (id INTEGER PRIMARY KEY REFERENCES semio_presentation_shape(id), kind TEXT NOT NULL, other TEXT);
CREATE TABLE semio_presentation_collection (id INTEGER PRIMARY KEY);
CREATE TABLE semio_presentation_member (id INTEGER PRIMARY KEY, collection_id INTEGER NOT NULL REFERENCES semio_presentation_collection(id), ordinal INTEGER NOT NULL, block_id INTEGER NOT NULL REFERENCES semio_presentation_block(id));
CREATE TABLE semio_presentation_block (id INTEGER PRIMARY KEY, kind TEXT NOT NULL);
CREATE TABLE semio_presentation_paragraph (id INTEGER PRIMARY KEY REFERENCES semio_presentation_block(id), style_id TEXT);
CREATE TABLE semio_presentation_heading (id INTEGER PRIMARY KEY REFERENCES semio_presentation_block(id), level INTEGER NOT NULL, style_id TEXT);
CREATE TABLE semio_presentation_run (id INTEGER PRIMARY KEY, block_id INTEGER NOT NULL REFERENCES semio_presentation_block(id), ordinal INTEGER NOT NULL, text TEXT NOT NULL, bold INTEGER NOT NULL, italic INTEGER NOT NULL, underline INTEGER NOT NULL, size REAL, font TEXT, color TEXT, link TEXT, size_ieee754_bits INTEGER, size_numeric_class TEXT);
CREATE TABLE semio_presentation_list (id INTEGER PRIMARY KEY REFERENCES semio_presentation_block(id), ordered INTEGER NOT NULL);
CREATE TABLE semio_presentation_list_item (id INTEGER PRIMARY KEY, list_id INTEGER NOT NULL REFERENCES semio_presentation_list(id), ordinal INTEGER NOT NULL, collection_id INTEGER NOT NULL REFERENCES semio_presentation_collection(id));
CREATE TABLE semio_presentation_table (id INTEGER PRIMARY KEY REFERENCES semio_presentation_block(id));
CREATE TABLE semio_presentation_table_row (id INTEGER PRIMARY KEY, table_id INTEGER NOT NULL REFERENCES semio_presentation_table(id), ordinal INTEGER NOT NULL);
CREATE TABLE semio_presentation_table_cell (id INTEGER PRIMARY KEY, row_id INTEGER NOT NULL REFERENCES semio_presentation_table_row(id), ordinal INTEGER NOT NULL, collection_id INTEGER NOT NULL REFERENCES semio_presentation_collection(id));
CREATE TABLE semio_presentation_code (id INTEGER PRIMARY KEY REFERENCES semio_presentation_block(id), language TEXT, text TEXT NOT NULL);
CREATE TABLE semio_presentation_quote (id INTEGER PRIMARY KEY REFERENCES semio_presentation_block(id), collection_id INTEGER NOT NULL REFERENCES semio_presentation_collection(id));
CREATE TABLE semio_presentation_image_block (id INTEGER PRIMARY KEY REFERENCES semio_presentation_block(id), image_id TEXT NOT NULL, alt TEXT NOT NULL, width REAL, height REAL, width_ieee754_bits INTEGER, width_numeric_class TEXT, height_ieee754_bits INTEGER, height_numeric_class TEXT);
CREATE TABLE semio_presentation_page_break (id INTEGER PRIMARY KEY REFERENCES semio_presentation_block(id));
